template:
// Pattern A: return an extendable quantity, update a global with the bent one.
// Diameter of Binary Tree (edges).
class Solution {
    int best = 0;
    int depth(TreeNode* n) {                 // longest downward chain, in nodes
        if (!n) return 0;                    // decide the null case first
        int L = depth(n->left), R = depth(n->right);
        best = max(best, L + R);             // path that BENDS at n — cannot be returned
        return 1 + max(L, R);                // path that can be EXTENDED by the parent
    }
public:
    int diameterOfBinaryTree(TreeNode* root) { depth(root); return best; }
};

// Pattern B: return a sentinel to short-circuit. Balanced Binary Tree.
int heightOrMinus1(TreeNode* n) {
    if (!n) return 0;
    int L = heightOrMinus1(n->left);  if (L < 0) return -1;
    int R = heightOrMinus1(n->right); if (R < 0) return -1;
    if (abs(L - R) > 1) return -1;
    return 1 + max(L, R);
}

// Pattern C: LCA — return the node found in this subtree.
TreeNode* lca(TreeNode* n, TreeNode* p, TreeNode* q) {
    if (!n || n == p || n == q) return n;
    TreeNode* L = lca(n->left, p, q);
    TreeNode* R = lca(n->right, p, q);
    if (L && R) return n;                    // one on each side → n is the answer
    return L ? L : R;                        // pass up whatever was found
}

// Pattern D: top-down — pass constraints DOWN. Validate BST.
bool valid(TreeNode* n, long lo, long hi) {
    if (!n) return true;
    if (n->val <= lo || n->val >= hi) return false;
    return valid(n->left, lo, n->val) && valid(n->right, n->val, hi);
}
